import{_ as l,o as e,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Testing Meeting 2018-09-26","description":"","frontmatter":{"title":"Ceph Testing Meeting 2018-09-26","date":"2018-09-26T00:00:00.000Z","updated":"2018-10-17T00:00:00.000Z","tags":["Ceph","分布式存储","测试","日志收集","PR处理","Jenkins","Python 3","SSH"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Testing_Meeting_2018-09-26.md","filePath":"posts/2018/Ceph_Testing_Meeting_2018-09-26.md","lastUpdated":1780459816000}'),s={name:"posts/2018/Ceph_Testing_Meeting_2018-09-26.md"};function o(r,i,a,p,g,h){return e(),t("div",null,[...i[0]||(i[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年9月26日</p><p><strong>参会人员</strong>： Nathan, David, Greg, Ricardo, Zach, Kier, Ron, Warren等</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及问题讨论</p><p><strong>关键细节</strong>：</p><ul><li><strong>测试问题</strong>： <ul><li>Nathan提出，Ceph集群中运行的任务，若运行时间超过12小时，则任务会被超时杀死，导致无法收集日志，影响调试。</li><li>讨论了两种解决方案：使用不同信号通知Ceph开始清理过程，或将清理工作拆分到不同进程。</li><li>决定优先解决日志收集问题，并在测试中添加超时机制。</li></ul></li><li><strong>PR处理</strong>： <ul><li>讨论了多个待处理的PR，包括Nathan的before teardown和dump context等。</li><li>决定合并部分PR，并处理冲突和问题。</li></ul></li><li><strong>其他事项</strong>： <ul><li>讨论了Ceph社区测试页面和Jenkins测试权限问题。</li><li>讨论了Python 3兼容性问题。</li><li>讨论了SSH pull request的合并问题。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>如何解决Ceph测试中日志收集问题。</li><li>如何处理待处理的PR。</li><li>如何改进Ceph测试和开发流程。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>优先解决日志收集问题，并考虑在测试中添加超时机制。</li><li>合并部分PR，并处理冲突和问题。</li><li>改进Ceph测试和开发流程。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Nathan将继续研究日志收集问题，并与团队讨论解决方案。</li><li>Greg将处理待处理的PR，并协助解决冲突和问题。</li><li>David和Zach将改进Ceph测试和开发流程。</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph</li><li>分布式存储</li><li>测试</li><li>日志收集</li><li>PR</li><li>Jenkins</li><li>Python 3</li><li>SSH</li><li>Ceph社区</li><li>JIRA</li></ul>',14)])])}const d=l(s,[["render",o]]);export{u as __pageData,d as default};
